namespace RecipeHub.Models;

public class Category
{
    public string Id { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public string Icon { get; set; } = string.Empty;
}

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string CategoryId { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }

    public double AverageRating => TotalRatings > 0 ? (double)RatingSum / TotalRatings : 0;
}

public class RecipeSubmission
{
    public string Title { get; set; } = string.Empty;
    public string CategoryId { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Category> _categories =
    [
        new() { Id = "breakfast", Name = "Breakfast", Description = "Start your day right", Icon = "🥞" },
        new() { Id = "lunch", Name = "Lunch", Description = "Midday meals and light bites", Icon = "🥗" },
        new() { Id = "dinner", Name = "Dinner", Description = "Hearty evening dishes", Icon = "🍝" },
        new() { Id = "desserts", Name = "Desserts", Description = "Sweet treats and baked goods", Icon = "🍰" },
        new() { Id = "drinks", Name = "Drinks", Description = "Beverages and smoothies", Icon = "🥤" },
    ];

    private readonly List<Recipe> _recipes =
    [
        new()
        {
            Id = 1, Title = "Classic Pancakes", CategoryId = "breakfast",
            Ingredients = "2 cups flour\n2 eggs\n1½ cups milk\n2 tbsp sugar\n2 tsp baking powder\n½ tsp salt\n2 tbsp melted butter",
            Steps = "1. Mix dry ingredients in a bowl.\n2. Whisk eggs, milk, and melted butter together.\n3. Combine wet and dry ingredients until just mixed.\n4. Heat a greased skillet over medium heat.\n5. Pour ¼ cup batter per pancake and cook until bubbles form.\n6. Flip and cook until golden brown.",
            TotalRatings = 12, RatingSum = 50
        },
        new()
        {
            Id = 2, Title = "Avocado Toast", CategoryId = "breakfast",
            Ingredients = "2 slices sourdough bread\n1 ripe avocado\n1 tbsp lemon juice\nSalt and pepper\nRed pepper flakes\n1 egg (optional)",
            Steps = "1. Toast the bread until golden and crispy.\n2. Mash the avocado with lemon juice, salt, and pepper.\n3. Spread avocado mixture on toast.\n4. Top with red pepper flakes.\n5. Add a fried or poached egg if desired.",
            TotalRatings = 8, RatingSum = 35
        },
        new()
        {
            Id = 3, Title = "Caesar Salad", CategoryId = "lunch",
            Ingredients = "1 head romaine lettuce\n½ cup croutons\n¼ cup parmesan cheese\n3 tbsp Caesar dressing\n1 grilled chicken breast (optional)",
            Steps = "1. Wash and chop the romaine lettuce.\n2. Toss lettuce with Caesar dressing.\n3. Add croutons and shaved parmesan.\n4. Slice grilled chicken and place on top.\n5. Serve immediately.",
            TotalRatings = 6, RatingSum = 25
        },
        new()
        {
            Id = 4, Title = "Grilled Cheese Sandwich", CategoryId = "lunch",
            Ingredients = "2 slices white bread\n2 slices cheddar cheese\n1 tbsp butter",
            Steps = "1. Butter one side of each bread slice.\n2. Place cheese between the unbuttered sides.\n3. Grill on medium heat until golden on each side.\n4. Slice diagonally and serve.",
            TotalRatings = 10, RatingSum = 42
        },
        new()
        {
            Id = 5, Title = "Spaghetti Bolognese", CategoryId = "dinner",
            Ingredients = "400g spaghetti\n500g ground beef\n1 onion, diced\n3 cloves garlic\n400g crushed tomatoes\n2 tbsp tomato paste\n1 tsp oregano\nSalt and pepper\nParmesan cheese",
            Steps = "1. Cook spaghetti according to package directions.\n2. Brown ground beef in a large pan and drain fat.\n3. Sauté onion and garlic until soft.\n4. Add crushed tomatoes, tomato paste, and oregano.\n5. Simmer sauce for 20 minutes.\n6. Serve sauce over spaghetti with parmesan.",
            TotalRatings = 15, RatingSum = 68
        },
        new()
        {
            Id = 6, Title = "Chicken Stir-Fry", CategoryId = "dinner",
            Ingredients = "2 chicken breasts, sliced\n2 cups mixed vegetables\n3 tbsp soy sauce\n1 tbsp sesame oil\n1 tbsp cornstarch\n2 cloves garlic\n1 tsp ginger\nCooked rice",
            Steps = "1. Mix soy sauce, sesame oil, and cornstarch for the sauce.\n2. Cook chicken in a hot wok until browned.\n3. Add garlic, ginger, and vegetables.\n4. Stir-fry for 3–4 minutes.\n5. Pour sauce over and toss to coat.\n6. Serve over steamed rice.",
            TotalRatings = 9, RatingSum = 40
        },
        new()
        {
            Id = 7, Title = "Chocolate Chip Cookies", CategoryId = "desserts",
            Ingredients = "2¼ cups flour\n1 cup butter, softened\n¾ cup sugar\n¾ cup brown sugar\n2 eggs\n1 tsp vanilla\n1 tsp baking soda\n2 cups chocolate chips",
            Steps = "1. Preheat oven to 375°F (190°C).\n2. Cream butter and sugars until fluffy.\n3. Beat in eggs and vanilla.\n4. Mix in flour and baking soda.\n5. Stir in chocolate chips.\n6. Drop spoonfuls onto baking sheet.\n7. Bake 9–11 minutes until golden.",
            TotalRatings = 20, RatingSum = 92
        },
        new()
        {
            Id = 8, Title = "Berry Smoothie", CategoryId = "drinks",
            Ingredients = "1 cup mixed berries\n1 banana\n1 cup yogurt\n½ cup milk\n1 tbsp honey",
            Steps = "1. Add all ingredients to a blender.\n2. Blend until smooth.\n3. Pour into a glass and serve immediately.",
            TotalRatings = 7, RatingSum = 30
        },
    ];

    private int _nextId = 9;

    public List<Category> GetCategories() => _categories;

    public Category? GetCategory(string categoryId) =>
        _categories.FirstOrDefault(c => c.Id == categoryId);

    public List<Recipe> GetRecipesByCategory(string categoryId) =>
        _recipes.Where(r => r.CategoryId == categoryId).ToList();

    public Recipe? GetRecipe(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalRatings++;
            recipe.RatingSum += stars;
        }
    }

    public Recipe AddRecipe(RecipeSubmission submission)
    {
        var recipe = new Recipe
        {
            Id = _nextId++,
            Title = submission.Title,
            CategoryId = submission.CategoryId,
            Ingredients = submission.Ingredients,
            Steps = submission.Steps
        };
        _recipes.Add(recipe);
        return recipe;
    }
}

