@page "/category/{CategoryId}"
@using RecipeHub.Models
@using RecipeHub.Services
@inject RecipeService RecipeService

<PageTitle>@(_category?.Name ?? "Category") — RecipeHub</PageTitle>

@if (_category is null)
{
    <h3>Category not found.</h3>
    <a href="/">Back to Home</a>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">@_category.Name</li>
        </ol>
    </nav>

    <h2>@_category.Icon @_category.Name</h2>
    <p class="text-muted">@_category.Description</p>

    @if (_recipes.Count == 0)
    {
        <div class="alert alert-info">No recipes in this category yet. <a href="submit">Submit one!</a></div>
    }
    else
    {
        <div class="list-group">
            @foreach (var recipe in _recipes)
            {
                <a href="recipe/@recipe.Id" class="list-group-item list-group-item-action d-flex justify-content-between align-items-center">
                    <div>
                        <h5 class="mb-1">@recipe.Title</h5>
                    </div>
                    <span class="badge bg-warning text-dark rounded-pill">
                        ⭐ @(recipe.TotalRatings > 0 ? recipe.AverageRating.ToString("0.0") : "No ratings")
                    </span>
                </a>
            }
        </div>
    }
}

@code {
    [Parameter] public string CategoryId { get; set; } = string.Empty;

    private Category? _category;
    private List<Recipe> _recipes = [];

    protected override void OnInitialized()
    {
        _category = RecipeService.GetCategory(CategoryId);
        if (_category is not null)
        {
            _recipes = RecipeService.GetRecipesByCategory(CategoryId);
        }
    }
}

@page "/recipe/{RecipeId:int}"
@using RecipeHub.Models
@using RecipeHub.Services
@inject RecipeService RecipeService

<PageTitle>@(_recipe?.Title ?? "Recipe") — RecipeHub</PageTitle>

@if (_recipe is null)
{
    <h3>Recipe not found.</h3>
    <a href="/">Back to Home</a>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="category/@_recipe.CategoryId">@(_category?.Name ?? _recipe.CategoryId)</a></li>
            <li class="breadcrumb-item active">@_recipe.Title</li>
        </ol>
    </nav>

    <h2>@_recipe.Title</h2>

    <div class="mb-4">
        <StarRating RecipeId="_recipe.Id" @rendermode="InteractiveServer" />
    </div>

    <div class="row">
        <div class="col-md-4">
            <div class="card mb-3">
                <div class="card-header"><strong>🧾 Ingredients</strong></div>
                <div class="card-body">
                    <ul class="list-unstyled mb-0">
                        @foreach (var line in _recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                        {
                            <li class="mb-1">• @line</li>
                        }
                    </ul>
                </div>
            </div>
        </div>
        <div class="col-md-8">
            <div class="card">
                <div class="card-header"><strong>👩‍🍳 Steps</strong></div>
                <div class="card-body">
                    @foreach (var line in _recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                    {
                        <p class="mb-2">@line</p>
                    }
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter] public int RecipeId { get; set; }

    private Recipe? _recipe;
    private Category? _category;

    protected override void OnInitialized()
    {
        _recipe = RecipeService.GetRecipe(RecipeId);
        if (_recipe is not null)
        {
            _category = RecipeService.GetCategory(_recipe.CategoryId);
        }
    }
}

@using RecipeHub.Services
@inject RecipeService RecipeService

<div class="d-inline-flex align-items-center gap-2">
    <span class="star-rating">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span class="star @(star <= _hovered ? "hovered" : "") @(star <= _selected ? "selected" : "")"
                  role="button"
                  @onmouseover="() => _hovered = star"
                  @onmouseout="() => _hovered = 0"
                  @onclick="() => SubmitRating(star)">
                ★
            </span>
        }
    </span>
    @if (_submitted)
    {
        <span class="text-success fw-bold">Thanks for rating!</span>
    }
    else
    {
        <span class="text-muted small">Click to rate</span>
    }
    @if (_recipe is not null && _recipe.TotalRatings > 0)
    {
        <span class="text-muted small ms-2">
            (@_recipe.AverageRating.ToString("0.0") avg · @_recipe.TotalRatings ratings)
        </span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }

    private int _hovered;
    private int _selected;
    private bool _submitted;
    private RecipeHub.Models.Recipe? _recipe;

    protected override void OnInitialized()
    {
        _recipe = RecipeService.GetRecipe(RecipeId);
    }

    private void SubmitRating(int stars)
    {
        if (_submitted) return;

        _selected = stars;
        RecipeService.AddRating(RecipeId, stars);
        _recipe = RecipeService.GetRecipe(RecipeId);
        _submitted = true;
    }
}

.star-rating {
    font-size: 1.8rem;
    cursor: pointer;
    user-select: none;
}

.star {
    color: #ddd;
    transition: color 0.15s;
}

.star.hovered,
.star.selected {
    color: #ffc107;
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeHub.Models
@using RecipeHub.Services
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe — RecipeHub</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">Submit Recipe</li>
    </ol>
</nav>

<h2>📝 Submit a Recipe</h2>
<p class="text-muted">Share your favorite recipe with the community.</p>

<div class="row">
    <div class="col-md-8">
        <EditForm Model="_submission" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
            <DataAnnotationsValidator />

            <div class="mb-3">
                <label for="title" class="form-label">Recipe Title</label>
                <InputText id="title" class="form-control" @bind-Value="_submission.Title" placeholder="e.g., Grandma's Apple Pie" />
            </div>

            <div class="mb-3">
                <label for="category" class="form-label">Category</label>
                <InputSelect id="category" class="form-select" @bind-Value="_submission.CategoryId">
                    <option value="">— Select a category —</option>
                    @foreach (var cat in RecipeService.GetCategories())
                    {
                        <option value="@cat.Id">@cat.Icon @cat.Name</option>
                    }
                </InputSelect>
            </div>

            <div class="mb-3">
                <label for="ingredients" class="form-label">Ingredients</label>
                <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="_submission.Ingredients" placeholder="One ingredient per line" />
            </div>

            <div class="mb-3">
                <label for="steps" class="form-label">Steps</label>
                <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="_submission.Steps" placeholder="Step-by-step instructions" />
            </div>

            <button type="submit" class="btn btn-success" disabled="@_submitting">
                @if (_submitting)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Submit Recipe
            </button>
        </EditForm>

        @if (!string.IsNullOrEmpty(_error))
        {
            <div class="alert alert-danger mt-3">@_error</div>
        }
    </div>
</div>

@code {
    private RecipeSubmission _submission = new();
    private bool _submitting;
    private string? _error;

    private void HandleSubmit()
    {
        _error = null;

        if (string.IsNullOrWhiteSpace(_submission.Title))
        {
            _error = "Please enter a recipe title.";
            return;
        }
        if (string.IsNullOrWhiteSpace(_submission.CategoryId))
        {
            _error = "Please select a category.";
            return;
        }
        if (string.IsNullOrWhiteSpace(_submission.Ingredients))
        {
            _error = "Please list the ingredients.";
            return;
        }
        if (string.IsNullOrWhiteSpace(_submission.Steps))
        {
            _error = "Please describe the preparation steps.";
            return;
        }

        _submitting = true;
        var recipe = RecipeService.AddRecipe(_submission);
        Navigation.NavigateTo($"recipe/{recipe.Id}");
    }
}

