@page "/recipe/{RecipeId:int}"
@using RecipeHub.Models
@using RecipeHub.Services
@inject RecipeService RecipeService

<PageTitle>@(_recipe?.Title ?? "Recipe") — RecipeHub</PageTitle>

@if (_recipe is null)
{
    <h3>Recipe not found.</h3>
    <a href="/">Back to Home</a>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="category/@_recipe.CategoryId">@(_category?.Name ?? _recipe.CategoryId)</a></li>
            <li class="breadcrumb-item active">@_recipe.Title</li>
        </ol>
    </nav>

    <h2>@_recipe.Title</h2>

    <div class="mb-4">
        <StarRating RecipeId="_recipe.Id" @rendermode="InteractiveServer" />
    </div>

    <div class="row">
        <div class="col-md-4">
            <div class="card mb-3">
                <div class="card-header"><strong>🧾 Ingredients</strong></div>
                <div class="card-body">
                    <ul class="list-unstyled mb-0">
                        @foreach (var line in _recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                        {
                            <li class="mb-1">• @line</li>
                        }
                    </ul>
                </div>
            </div>
        </div>
        <div class="col-md-8">
            <div class="card">
                <div class="card-header"><strong>👩‍🍳 Steps</strong></div>
                <div class="card-body">
                    @foreach (var line in _recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                    {
                        <p class="mb-2">@line</p>
                    }
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter] public int RecipeId { get; set; }

    private Recipe? _recipe;
    private Category? _category;

    protected override void OnInitialized()
    {
        _recipe = RecipeService.GetRecipe(RecipeId);
        if (_recipe is not null)
        {
            _category = RecipeService.GetCategory(_recipe.CategoryId);
        }
    }
}

@using RecipeHub.Services
@inject RecipeService RecipeService

<div class="d-inline-flex align-items-center gap-2">
    <span class="star-rating">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span class="star @(star <= _hovered ? "hovered" : "") @(star <= _selected ? "selected" : "")"
                  role="button"
                  @onmouseover="() => _hovered = star"
                  @onmouseout="() => _hovered = 0"
                  @onclick="() => SubmitRating(star)">
                ★
            </span>
        }
    </span>
    @if (_submitted)
    {
        <span class="text-success fw-bold">Thanks for rating!</span>
    }
    else
    {
        <span class="text-muted small">Click to rate</span>
    }
    @if (_recipe is not null && _recipe.TotalRatings > 0)
    {
        <span class="text-muted small ms-2">
            (@_recipe.AverageRating.ToString("0.0") avg · @_recipe.TotalRatings ratings)
        </span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }

    private int _hovered;
    private int _selected;
    private bool _submitted;
    private RecipeHub.Models.Recipe? _recipe;

    protected override void OnInitialized()
    {
        _recipe = RecipeService.GetRecipe(RecipeId);
    }

    private void SubmitRating(int stars)
    {
        if (_submitted) return;

        _selected = stars;
        RecipeService.AddRating(RecipeId, stars);
        _recipe = RecipeService.GetRecipe(RecipeId);
        _submitted = true;
    }
}

