toolArgs.file_text:
@page "/submit"
@rendermode InteractiveServer
@using RecipeHub.Models
@using RecipeHub.Services
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe — RecipeHub</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">Submit Recipe</li>
    </ol>
</nav>

<h2>📝 Submit a Recipe</h2>
<p class="text-muted">Share your favorite recipe with the community.</p>

<div class="row">
    <div class="col-md-8">
        <EditForm Model="_submission" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
            <DataAnnotationsValidator />

            <div class="mb-3">
                <label for="title" class="form-label">Recipe Title</label>
                <InputText id="title" class="form-control" @bind-Value="_submission.Title" placeholder="e.g., Grandma's Apple Pie" />
            </div>

            <div class="mb-3">
                <label for="category" class="form-label">Category</label>
                <InputSelect id="category" class="form-select" @bind-Value="_submission.CategoryId">
                    <option value="">— Select a category —</option>
                    @foreach (var cat in RecipeService.GetCategories())
                    {
                        <option value="@cat.Id">@cat.Icon @cat.Name</option>
                    }
                </InputSelect>
            </div>

            <div class="mb-3">
                <label for="ingredients" class="form-label">Ingredients</label>
                <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="_submission.Ingredients" placeholder="One ingredient per line" />
            </div>

            <div class="mb-3">
                <label for="steps" class="form-label">Steps</label>
                <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="_submission.Steps" placeholder="Step-by-step instructions" />
            </div>

            <button type="submit" class="btn btn-success" disabled="@_submitting">
                @if (_submitting)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Submit Recipe
            </button>
        </EditForm>

        @if (!string.IsNullOrEmpty(_error))
        {
            <div class="alert alert-danger mt-3">@_error</div>
        }
    </div>
</div>

@code {
    private RecipeSubmission _submission = new();
    private bool _submitting;
    private string? _error;

    private void HandleSubmit()
    {
        _error = null;

        if (string.IsNullOrWhiteSpace(_submission.Title))
        {
            _error = "Please enter a recipe title.";
            return;
        }
        if (string.IsNullOrWhiteSpace(_submission.CategoryId))
        {
            _error = "Please select a category.";
            return;
        }
        if (string.IsNullOrWhiteSpace(_submission.Ingredients))
        {
            _error = "Please list the ingredients.";
            return;
        }
        if (string.IsNullOrWhiteSpace(_submission.Steps))
        {
            _error = "Please describe the preparation steps.";
            return;
        }

        _submitting = true;
        var recipe = RecipeService.AddRecipe(_submission);
        Navigation.NavigateTo($"recipe/{recipe.Id}");
    }
}

